   102	function collectBinFiles(bin: Record<string, string> | string | undefined) {
   103		if (!bin) {
   104			return [];
   105		}
   106	
   107		const files = typeof bin === "object" ? Object.values(bin) : [bin];
   108	
   109		return files.map((file) => file.replace(/^\.\//, ""));
   110	}
   111	
   112	function processFiles(files: string[]) {
   113		// First sort so that shorter entries are first (e.g. "lib/")...
   114		const sortedByLength = files
   115			.filter(Boolean)
   116			.sort((a, b) => a.length - b.length);
   117	
   118		// ...then remove entries captured by earlier directories (e.g. "lib/index.js")
   119		return sortedByLength
   120			.filter(
   121				(file, i) =>
   122					!sortedByLength
   123						.slice(0, i)
   124						.some((earlier) => earlier.endsWith("/") && file.startsWith(earlier)),
   125			)
   126			.sort();
   127	}
   128	
   129	function removeRangePrefix(version: string) {
   130		const raw = version.replaceAll(/[\^~><=]/gu, "").split(" ")[0];
   131	
   132		return semver.coerce(raw) ?? raw;
   133	}
   134	
   135	function useLargerVersion(existing: string | undefined, replacement: string) {
   136		if (!existing || existing === replacement) {
   137			return replacement;
   138		}
   139	
   140		const existingCoerced = semver.coerce(removeRangePrefix(existing));
   141	
   142		return existingCoerced &&
   143			semver.gt(existingCoerced, removeRangePrefix(replacement))
   144			? existing
   145			: replacement;
   146	}
   147	
   148	function useLargerVersions(
   149		existing: Record<string, string | undefined> | undefined,
   150		replacements: Record<string, string>,
   151	) {
   152		if (!existing) {
   153			return replacements;
   154		}
   155	
   156		return Object.fromEntries(
   157			Object.entries(replacements).map(([key, replacement]) => [
   158				key,
   159				useLargerVersion(existing[key], replacement),
   160			]),
   161		);
   162	}
