package day12

import "sort"

// UniqueClimbs recursively explores every possible first stride,
// summing the results of sub-problems. Runs in exponential time.
// Returns 0 for negative steps, 1 when steps is 0.
func UniqueClimbs(steps int, strides []int) int {
	if steps < 0 {
		return 0
	}
	if steps == 0 {
		return 1
	}
	total := 0
	for _, s := range strides {
		total += UniqueClimbs(steps-s, strides)
	}
	return total
}

// UniqueClimbsDS uses dynamic programming with memoization
// (bottom-up iteration) to compute the result in O(K·N) time,
// where K is the number of stride options and N is steps.
func UniqueClimbsDS(steps int, strides []int) int {
	if steps < 0 {
		return 0
	}
	if steps == 0 {
		return 1
	}
	sort.Ints(strides)
	dp := make([]int, steps+1)
	dp[0] = 1
	for i := 1; i <= steps; i++ {
		for _, s := range strides {
			if i-s >= 0 {
				dp[i] += dp[i-s]
			}
		}
	}
	return dp[steps]
}
EOF
