// splice(arr, start[, deleteCount[, item1[, item2[, ...]]]])
func builtinSplice(args ...Object) (Object, error) {
	if len(args) < 2 {
		return nil, ErrWrongNumArguments
	}
	arr, ok := args[0].(*Array)
	if !ok {
		return nil, ErrInvalidArgumentType{
			Name:     "first",
			Expected: "array",
			Found:    args[0].TypeName(),
		}
	}
	startInt, ok := args[1].(*Int)
	if !ok {
		return nil, ErrInvalidArgumentType{
			Name:     "second",
			Expected: "int",
			Found:    args[1].TypeName(),
		}
	}
	start := int(startInt.Value)
	if start < 0 || start > len(arr.Value) {
		return nil, ErrIndexOutOfBounds
	}
	deleteCount := len(arr.Value) - start
	if len(args) > 2 {
		delCountInt, ok := args[2].(*Int)
		if !ok {
			return nil, ErrInvalidArgumentType{
				Name:     "third",
				Expected: "int",
				Found:    args[2].TypeName(),
			}
		}
		deleteCount = int(delCountInt.Value)
		if deleteCount < 0 {
			return nil, ErrIndexOutOfBounds
		}
	}
	removed := arr.Value[start : start+deleteCount]
	arr.Value = append(arr.Value[:start], arr.Value[start+deleteCount:]...)
	insertArgs := args[3:]
	if len(insertArgs) > 0 {
		arr.Value = append(arr.Value[:start], append(insertArgs, arr.Value[start:]...)...)
	}
	return &Array{Value: removed}, nil
}
