   369	// LoadControllers loads a list of controllers from the kubeResources Pods
   370	func LoadControllers(ctx context.Context, pods []corev1.Pod, dynamicClientPointer *dynamic.Interface, restMapperPointer *meta.RESTMapper, objectCache map[string]unstructured.Unstructured) ([]GenericResource, error) {
   371		interfaces := []GenericResource{}
   372		deduped := map[string]corev1.Pod{}
   373		for _, pod := range pods {
   374			owners := pod.ObjectMeta.OwnerReferences
   375			if len(owners) == 0 {
   376				deduped[pod.ObjectMeta.Namespace+"/Pod/"+pod.ObjectMeta.Name] = pod
   377				continue
   378			}
   379			deduped[pod.ObjectMeta.Namespace+"/"+owners[0].Kind+"/"+owners[0].Name] = pod
   380		}
   381		for _, pod := range deduped {
   382			workload, err := ResolveControllerFromPod(ctx, pod, dynamicClientPointer, restMapperPointer, objectCache)
   383			if err != nil {
   384				return nil, err
   385			}
   386			interfaces = append(interfaces, workload)
   387		}
   388		return interfaces, nil
   389	}
