   391	// Because the controllers with an Owner take on the name of the Owner, this eliminates any duplicates.
   392	// In cases like CronJobs older children can hang around, so this takes the most recent.
   393	func deduplicateControllers(inputResources []GenericResource) []GenericResource {
   394		controllerMap := make(map[string]GenericResource)
   395		for _, controller := range inputResources {
   396			key := controller.ObjectMeta.GetNamespace() + "/" + controller.Kind + "/" + controller.ObjectMeta.GetName()
   397			oldController, ok := controllerMap[key]
   398			if !ok || controller.ObjectMeta.GetCreationTimestamp().Time.After(oldController.ObjectMeta.GetCreationTimestamp().Time) {
   399				controllerMap[key] = controller
   400			}
   401		}
   402		results := make([]GenericResource, len(controllerMap))
   403		idx := 0
   404		for _, controller := range controllerMap {
   405			results[idx] = controller
   406			idx++
   407		}
   408		return results
   409	}
