   424		specs := regexp.MustCompile("[\r\n]-+[\r\n]").Split(string(contents), -1)
   425		for _, spec := range specs {
   426			if strings.TrimSpace(spec) == "" {
   427				continue
   428			}
   429			err := resources.addResourceFromString(spec)
   430			if err != nil {
