   438	func (resources *ResourceProvider) addResourceFromString(contents string) error {
   439		contentBytes := []byte(contents)
   440		decoder := k8sYaml.NewYAMLOrJSONDecoder(bytes.NewReader(contentBytes), 1000)
   441		resource := k8sResource{}
   442		err := decoder.Decode(&resource)
   443		decoder = k8sYaml.NewYAMLOrJSONDecoder(bytes.NewReader(contentBytes), 1000)
   444	
   445		if err != nil {
